
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_br89_1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_br89_1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.417182490551891e+00, -3.405262140483787e+00, -3.383368625746267e+00, -3.343443974611473e+00, -3.272051260510122e+00, -3.148565964527720e+00, -2.945276335870961e+00, -2.635593013575222e+00, -2.218120772840455e+00, -1.730695377981881e+00, -1.206439127729462e+00, -7.109455675745232e-01, -5.669156860238466e-01, -4.988224168949025e-01, -3.941512006284132e-01, -2.741388701197074e-01, -1.789338274229471e-01, -1.160053015619750e-01, -7.664650516949552e-02, -5.154288530268863e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


